create temporary table fox_pack_protected on commit drop as
select 'user_items' as tbl,to_jsonb(t) as value from public.user_items t
union all select 'user_packs',to_jsonb(t) from public.user_packs t
union all select 'stock_history',to_jsonb(t) from public.stock_history t
union all select 'packs',to_jsonb(t) from public.packs t
union all select 'contents',to_jsonb(t) from public.pack_contents t where not exists(select 1 from fox_pack_delta d where d.pack_id=t.pack_id and d.item=t.item);
do $$ begin
if exists(select 1 from fox_pack_identity i left join public.packs p on p.id=i.id where p.id is null or p.name<>i.name or p.price<>i.price) then raise exception 'Pack identity or price changed; review again'; end if;
if exists(select 1 from fox_pack_delta d join public.pack_contents c on c.pack_id=d.pack_id and c.item=d.item group by d.pack_id,d.item having count(*)>1) then raise exception 'Duplicate contents'; end if;
if exists(select 1 from fox_pack_delta d left join public.pack_contents c on c.pack_id=d.pack_id and c.item=d.item where coalesce(c.qty,0)<>d.old_qty and coalesce(c.qty,0)<>d.new_qty) then raise exception 'Contents changed since review; update cancelled'; end if;
end $$;
update public.pack_contents c set qty=d.new_qty from fox_pack_delta d where c.pack_id=d.pack_id and c.item=d.item and d.new_qty>0 and c.qty<>d.new_qty;
insert into public.pack_contents(pack_id,item,qty) select d.pack_id,d.item,d.new_qty from fox_pack_delta d where d.new_qty>0 and not exists(select 1 from public.pack_contents c where c.pack_id=d.pack_id and c.item=d.item);
delete from public.pack_contents c using fox_pack_delta d where c.pack_id=d.pack_id and c.item=d.item and d.new_qty=0;
do $$ begin
if exists(select 1 from fox_pack_delta d left join public.pack_contents c on c.pack_id=d.pack_id and c.item=d.item where coalesce(c.qty,0)<>d.new_qty) then raise exception 'Content verification failed'; end if;
if exists(
(select * from fox_pack_protected except all
(select 'user_items',to_jsonb(t) from public.user_items t union all select 'user_packs',to_jsonb(t) from public.user_packs t union all select 'stock_history',to_jsonb(t) from public.stock_history t union all select 'packs',to_jsonb(t) from public.packs t union all select 'contents',to_jsonb(t) from public.pack_contents t where not exists(select 1 from fox_pack_delta d where d.pack_id=t.pack_id and d.item=t.item)))
) then raise exception 'Protected data changed; rolling back'; end if;
end $$;
select count(distinct pack_id) as packs_verified,count(*) as content_changes_verified from fox_pack_delta;
commit;
